function getAnsibleTranslation(key, lang) {
    if (ansibleTranslations[lang] && ansibleTranslations[lang][key]) {
        return ansibleTranslations[lang][key];
    }
    if (ansibleTranslations.en && ansibleTranslations.en[key]) {
        return ansibleTranslations.en[key];
    }
    return null;
}

function applyAnsibleTranslations(lang) {
    console.log('Applying ansible translations for:', lang);
    let count = 0;
    document.querySelectorAll('[data-i18n]').forEach(element => {
        const key = element.getAttribute('data-i18n');
        if (key && key.startsWith('review.ansible.')) {
            const translation = getAnsibleTranslation(key, lang);
            if (translation) {
                element.textContent = translation;
                count++;
            }
        }
    });
    console.log(`Applied ${count} ansible translations`);
}

window.addEventListener('languageChanged', (e) => {
    const lang = e.detail.language;
    setTimeout(() => applyAnsibleTranslations(lang), 200);
});

if (document.readyState === 'loading') {
    document.addEventListener('DOMContentLoaded', () => {
        const currentLang = window.i18n ? window.i18n.getCurrentLanguage() : 'en';
        applyAnsibleTranslations(currentLang);
    });
} else {
    const currentLang = window.i18n ? window.i18n.getCurrentLanguage() : 'en';
    applyAnsibleTranslations(currentLang);
}

console.log('ansible i18n loaded');
